"""Writes assets/showcase/island.cmds: a small island, built with Voxferro's
console commands (run it with `voxferro --script assets/showcase/island.cmds`).

Deterministic: the "noise" is a fixed hash, so the island is the same on
every run."""
import math, pathlib

N, H = 64, 40
out = ["# A small island at dusk, as Voxferro console commands.",
       "# Generated by scripts/showcase/island.py.",
       f"new {N} {N} {H}"]

pal = {1: (226, 206, 150),   # sand
       2: (98, 158, 62),     # grass
       3: (72, 128, 50),     # grass, darker
       4: (120, 116, 110),   # rock
       5: (70, 140, 200),    # water
       6: (104, 70, 44),     # trunk
       7: (56, 120, 52),     # leaves
       8: (86, 150, 64),     # leaves, light
       9: (236, 232, 222),   # walls
       10: (176, 58, 44),    # roof
       11: (255, 196, 110),  # lit windows
       12: (240, 240, 245),  # cloud
       13: (82, 60, 44),     # door
       14: (255, 220, 150)}  # lantern
for i, (r, g, b) in pal.items():
    out.append(f"palette {i} {r} {g} {b}")
out += ["material 5 metal metal=0.25 rough=0.12",
        "material 11 emit emit=1 flux=2",
        "material 14 emit emit=1 flux=3",
        "material 12 cloud media=1 density=0.4"]

def hash2(x, y):
    h = (x * 374761393 + y * 668265263) & 0xFFFFFFFF
    h = ((h ^ (h >> 13)) * 1274126177) & 0xFFFFFFFF
    return (h & 0xFFFF) / 0xFFFF

def smooth(x, y, scale):
    gx, gy = x / scale, y / scale
    x0, y0 = int(gx), int(gy)
    fx, fy = gx - x0, gy - y0
    fx, fy = fx * fx * (3 - 2 * fx), fy * fy * (3 - 2 * fy)
    a, b = hash2(x0, y0), hash2(x0 + 1, y0)
    c, d = hash2(x0, y0 + 1), hash2(x0 + 1, y0 + 1)
    return (a * (1 - fx) + b * fx) * (1 - fy) + (c * (1 - fx) + d * fx) * fy

cells = {}
def put(x, y, z, c):
    if 0 <= x < N and 0 <= y < N and 0 <= z < H:
        cells[(x, y, z)] = c

height = {}
cx, cy = 30, 32
for y in range(N):
    for x in range(N):
        r = math.hypot((x - cx) * 1.0, (y - cy) * 1.25)
        n = smooth(x, y, 9) * 0.6 + smooth(x, y, 4) * 0.4
        h = 9.0 * (1 - r / 24) + 3.5 * (n - 0.5)
        h = int(round(h))
        height[(x, y)] = h
        for z in range(0, max(h, 0) + 1):
            if h <= 1:
                c = 1
            elif z == h:
                c = 2 if n > 0.45 else 3
            elif z >= h - 1:
                c = 1 if h <= 2 else 4
            else:
                c = 4
            put(x, y, z, c)
        # A sandy bed at z = 0 under one layer of water, so the glass has
        # something to show through.
        if h < 1:
            put(x, y, 0, 1)
            put(x, y, 1, 5)

def ground(x, y):
    return height.get((x, y), 0)

# Trees: a trunk and a rounded canopy.
for (tx, ty, th) in [(20, 30, 6), (24, 40, 7), (36, 24, 5), (40, 38, 6), (18, 38, 5)]:
    g = ground(tx, ty)
    if g < 2:
        continue
    for z in range(g + 1, g + th):
        put(tx, ty, z, 6)
    top = g + th
    for dz in range(-2, 3):
        for dy in range(-3, 4):
            for dx in range(-3, 4):
                if dx * dx + dy * dy + (dz * 1.4) ** 2 <= 9.5:
                    put(tx + dx, ty + dy, top + dz, 8 if (dx + dy + dz) % 3 == 0 else 7)

# A small house with lit windows and a pitched roof.
hx, hy = 28, 30
base = max(ground(x, y) for x in range(hx, hx + 9) for y in range(hy, hy + 7)) + 1
for x in range(hx, hx + 9):
    for y in range(hy, hy + 7):
        for z in range(min(ground(x, y) + 1, base), base):
            put(x, y, z, 4)  # foundation down to the slope
        for z in range(base, base + 5):
            edge = x in (hx, hx + 8) or y in (hy, hy + 6)
            if edge:
                put(x, y, z, 9)
for (x, y, z) in [(hx + 2, hy, base + 2), (hx + 6, hy, base + 2), (hx, hy + 3, base + 2), (hx + 8, hy + 3, base + 2)]:
    put(x, y, z, 11)
for z in range(base, base + 3):
    put(hx + 4, hy, z, 13)
for i in range(5):
    for x in range(hx - 1, hx + 10):
        put(x, hy - 1 + i, base + 5 + i, 10)
        put(x, hy + 7 - i, base + 5 + i, 10)
    for x in (hx, hx + 8):
        for y in range(hy + i, hy + 7 - i):
            put(x, y, base + 5 + i, 9)
# A lantern by the door.
put(hx + 6, hy - 2, base, 6); put(hx + 6, hy - 2, base + 1, 6); put(hx + 6, hy - 2, base + 2, 14)

# Two clouds.
for (ccx, ccy, ccz) in [(14, 14, 32), (46, 50, 30)]:
    for dz in range(-2, 3):
        for dy in range(-4, 5):
            for dx in range(-7, 8):
                if (dx / 7) ** 2 + (dy / 4) ** 2 + (dz / 2.2) ** 2 <= 1 and hash2(dx + ccx, dy * 7 + dz) > 0.15:
                    put(ccx + dx, ccy + dy, ccz + dz, 12)

items = sorted(cells.items())
for i in range(0, len(items), 400):
    chunk = items[i:i + 400]
    out.append("voxels " + " ".join(f"{x} {y} {z} {c}" for (x, y, z), c in chunk))

out += ["env atmosphere 55", "camera iso", "camera persp", "camera frame", "camera zoom 0.72"]
path = pathlib.Path(__file__).resolve().parents[2] / "assets/showcase/island.cmds"
path.write_text("\n".join(out) + "\n")
print(f"{path}: {len(items)} voxels, {len(out)} lines")
